items=[]
def add(id,title,kind,task,body,replacements,logic,check,phrases,header='',footer='',source='S16、S18、S19；功能与格式综合重写'):
    paras=body.strip().split('\n\n')
    template=body.strip()
    for old,new in sorted(replacements.items(),key=lambda x:-len(x[0])):
        if old not in template:raise ValueError((id,old))
        template=template.replace(old,'【'+new+'】')
    items.append(dict(id=id,title=title,kind=kind,task=task,body=paras,template=template.split('\n\n'),logic=logic,check=check,phrases=phrases,header=header,footer=footer,source=source))

add('A01','邀请信','书信','新编题：作为英语社团组织者，邀请 Smith 教授参加阅读交流会；交代活动内容、时间地点和希望对方承担的任务。', '''Our English Society is arranging a reading workshop, and we would be delighted to have you as our guest speaker.

We will meet in Room 203 at two on Friday afternoon. Students will first discuss a short story in small groups. We hope you can then explain how to read beyond the plot and answer a few questions. Your experience would help beginners approach English fiction with greater confidence. The session should take about an hour, and we can adjust the speaking time to suit your schedule.

Could you let me know by Wednesday whether you can join us?''',{'Our English Society':'主办方','a reading workshop':'活动名称，含冠词','our guest speaker':'受邀身份','in Room 203 at two on Friday afternoon':'地点＋具体时间','discuss a short story in small groups':'参加者要做的事，动词原形','explain how to read beyond the plot and answer a few questions':'希望对方承担的任务，动词原形','approach English fiction with greater confidence':'对参加者的具体帮助，动词原形','about an hour':'预计时长','Wednesday':'回复期限'},'邀请及身份 → 时间地点、流程及作用 → 确认是否出席','邀请谁做什么必须明确；to suit your schedule 只表示可协商，不要擅自修改题干已定时间。',[('have you as our guest speaker','邀请您担任嘉宾；as 后接角色'),('read beyond the plot','读懂情节背后的含义；适合阅读活动'),('adjust ... to suit ...','调整……以适应……')],header='Dear Professor Smith,',footer='Yours sincerely,\nLi Ming')
add('A02','推荐信：书籍／活动／地点','书信','新编题：朋友 David 想了解本地文化，向他推荐一处周末可去的地方，说明两条理由并给出游览建议。','''For your weekend visit, I would choose the City History Museum. It seems a good match for your interest in everyday life in China.

The displays explain how local families lived, worked and celebrated festivals. Short English descriptions make the stories easy to follow, even without much background knowledge. There is also a workshop where visitors can try traditional printing. You could therefore learn about the past while making something yourself. I suggest going early, since this would leave you enough time for both the exhibition and the workshop.

Tell me if you decide to go; I would enjoy joining you.''',{'your weekend visit':'对方的活动安排','the City History Museum':'推荐对象','everyday life in China':'对方的兴趣','The displays explain how local families lived, worked and celebrated festivals.':'推荐理由一，完整句','Short English descriptions make the stories easy to follow, even without much background knowledge.':'理由一的具体支撑，完整句','There is also a workshop where visitors can try traditional printing.':'推荐理由二，完整句','learn about the past while making something yourself':'具体收获，动词原形','going early':'行动建议，动名词','the exhibition and the workshop':'两个相关环节'},'推荐对象 → 两个可核实特点与需求匹配 → 实用提示','推荐对象可以换成书、课程或展览，但理由也要随之改写；不要保留与新对象无关的 museum/workshop。',[('a good match for','与……很合适'),('background knowledge','背景知识，不可数'),('leave ... enough time for ...','给……留出足够时间')],header='Dear David,',footer='Best wishes,\nLi Ming')
add('A03','推荐信：推荐他人','书信','新编题：向项目负责人推荐同学 Chen Yu 担任博物馆志愿讲解员，交代关系、能力及具体经历。','''May I recommend Chen Yu for the museum guide position? We worked together on a campus history project last term, so I have seen how carefully she prepares and communicates.

She can explain unfamiliar ideas in clear English and is patient with questions. During our project, she turned several difficult historical accounts into short stories that visitors could easily understand. She also checked every date against the original records. These habits would be useful when guiding groups with different levels of knowledge.

I believe she could make a reliable addition to your team. I can provide further details about our work if needed.''',{'Chen Yu':'被推荐人姓名','the museum guide position':'推荐职位','a campus history project last term':'共同经历及时间','She can explain unfamiliar ideas in clear English and is patient with questions.':'与岗位相关的能力，完整句','she turned several difficult historical accounts into short stories that visitors could easily understand':'能力证据，完整分句','She also checked every date against the original records.':'另一项能力证据，完整句','guiding groups with different levels of knowledge':'岗位具体工作，动名词'},'推荐及关系 → 能力与可观察证据 → 明确推荐','she/her 应随人物一致替换；推荐人只能声称自己有依据的经历，不能只堆 excellent、outstanding。',[('check ... against ...','对照……核查……'),('a reliable addition to your team','团队中可靠的新成员'),('if needed','如有需要')],header='Dear Project Coordinator,',footer='Yours sincerely,\nLi Ming',source='S06、S18、S29；推荐功能与证据表达综合重写')
add('A04','建议信','书信','新编题：朋友 Jack 要做英语口头报告，给出准备建议并说明这些做法有什么帮助。','''Your presentation sounds interesting, and a few simple steps may make the preparation easier.

Start by choosing one question that you want your audience to understand. Collect two or three examples to answer it, instead of including every fact you find. Next, practise aloud with a timer. This will show you which parts need shortening and help you speak at a comfortable pace. You could also ask a classmate to listen and point out anything unclear. Keep the slides brief so that people can focus on what you say.

I would be happy to listen to a practice run this weekend.''',{'Your presentation':'需要准备的任务','choosing one question that you want your audience to understand':'建议一，动名词','Collect two or three examples to answer it, instead of including every fact you find.':'具体操作，完整句','practise aloud with a timer':'建议二，动词原形','This will show you which parts need shortening and help you speak at a comfortable pace.':'建议二的作用，完整句','ask a classmate to listen and point out anything unclear':'补充建议，动词原形','Keep the slides brief so that people can focus on what you say.':'针对本任务的提示，完整句','listen to a practice run this weekend':'愿提供的帮助，动词原形'},'回应困难 → 可执行步骤及理由 → 后续支持','建议必须与来信中的困难对应；suggest 后用 doing 或 that 从句，不能写 suggest you to do。',[('practise aloud with a timer','计时大声练习'),('at a comfortable pace','以舒适的速度'),('point out anything unclear','指出不清楚的地方')],header='Dear Jack,',footer='Best wishes,\nLi Ming')
add('A05','计划信：提出方案并征求意见','书信','新编题：你和 Jack 准备调查校园旧物再利用情况；提出调查计划并询问他的意见。','''For our survey on the reuse of unwanted items, I suggest starting with the student residences. This would let us reach people who regularly exchange books and household goods.

We could prepare five short questions about what students exchange and what difficulties they encounter. I can draft the questions, while you arrange interviews with a few residents. After collecting the answers, we could group the main problems and discuss possible improvements. Saturday morning would work for me, but we should check when the residents are available.

Does this approach sound reasonable to you? Please suggest any changes before we begin contacting people.''',{'the reuse of unwanted items':'调查主题','the student residences':'调查地点或群体','This would let us reach people who regularly exchange books and household goods.':'选择理由，完整句','five short questions about what students exchange and what difficulties they encounter':'调查问题设计','draft the questions':'我的分工，动词原形','arrange interviews with a few residents':'你的分工，动词原形','group the main problems and discuss possible improvements':'后续分析步骤，动词原形','Saturday morning':'拟定时间','the residents':'受访对象'},'提出计划 → 方法、分工和时间 → 征求修改意见','共同计划用 could 表示提议；征求意见必须明写，不要只用期待回信收尾。',[('group the main problems','归类主要问题'),('check when ... are available','确认……何时有空'),('Does this approach sound reasonable to you?','明确征求意见')],header='Dear Jack,',footer='Best wishes,\nLi Ming')
add('A06','介绍信：介绍项目并邀请参与','书信','新编题：向国际学生介绍校园故事展，并邀请他们分享家乡故事、说明参与方式。','''Our campus storytelling exhibition will open next month, and I hope you will contribute a story from your hometown.

The exhibition will explore how ordinary places become part of people's memories. Each participant will provide one photograph and a short English description explaining its personal meaning. We will display the contributions in the student centre and hold a discussion on the opening afternoon. No special writing experience is required; a clear and honest account is enough. Your stories would give other students a chance to discover places through the people who know them.

Please send your contribution to the exhibition team by Friday.''',{'Our campus storytelling exhibition':'项目名称','next month':'举办时间','contribute a story from your hometown':'邀请对方做的事，动词原形','how ordinary places become part of people\'s memories':'项目主题，名词性从句','one photograph and a short English description explaining its personal meaning':'参与者提交的材料','in the student centre':'地点介词短语','hold a discussion on the opening afternoon':'活动安排，动词原形','a clear and honest account':'合格材料的特点','discover places through the people who know them':'参加者的收获，动词原形','the exhibition team':'提交对象','Friday':'截止时间'},'是什么 → 怎么参与、有什么价值 → 明确邀请与提交方式','介绍与邀请是两个任务，都要有具体内容；若题目要求邮箱或报名地点，应补全。',[('contribute a story','提供／分享一则故事'),('a clear and honest account','清楚真实的叙述'),('No special ... is required','不要求专门的……')],header='Dear International Students,',footer='Best wishes,\nLi Ming')
add('A07','答复信：回复咨询','书信','新编题：Anna 来信询问志愿教学项目的工作、安排和准备事项，逐项回复。','''You asked about our weekend teaching project. I am glad you are considering joining us, and here are the details you need.

Volunteers help local children practise basic English through games and short conversations. Sessions take place at the community centre on Saturday mornings, with each volunteer working alongside an experienced teacher. You do not need to prepare a full lesson alone. Before your first visit, please read the activity guide and bring one simple game idea. The coordinator will explain the children's needs and help you adapt your materials.

If this arrangement suits you, I can introduce you to the coordinator.''',{'our weekend teaching project':'对方咨询的项目','Volunteers help local children practise basic English through games and short conversations.':'回答工作内容，完整句','Sessions take place at the community centre on Saturday mornings, with each volunteer working alongside an experienced teacher.':'回答时间地点与组织方式，完整句','You do not need to prepare a full lesson alone.':'补充要求，完整句','your first visit':'相关活动','read the activity guide and bring one simple game idea':'准备事项，动词原形','The coordinator will explain the children\'s needs and help you adapt your materials.':'支持安排，完整句','the coordinator':'可联系的负责人'},'回应来信 → 按问题顺序逐项回答 → 后续联系','先圈出来信里的每个问句，再检查是否一一作答；不要用笼统的活动意义代替答案。',[('work alongside','与……一起工作'),('adapt your materials','调整你的材料以适应需要'),('If this arrangement suits you','如果这样的安排适合你')],header='Dear Anna,',footer='Best wishes,\nLi Ming')
add('A08','交流信：表达感受并询问详情','书信','新编题：朋友 Jack 分享了家庭旅行视频；表达具体感受，并询问希望进一步了解的旅行细节。','''I watched your travel video yesterday and especially enjoyed the scene where your family learned to make noodles. The laughter made the experience feel warm and personal.

It was interesting to see how a simple meal brought you together with local people. Your video also made me curious about the rest of the journey. How did you find the cooking workshop, and which place surprised you most? I would also love to know whether travelling with your parents changed the way you planned each day.

When you have time, please share a few more stories. I would really enjoy hearing them.''',{'your travel video':'对方分享的内容','yesterday':'观看或阅读时间','your family learned to make noodles':'具体打动你的情节，完整分句','The laughter made the experience feel warm and personal.':'感受及依据，完整句','how a simple meal brought you together with local people':'进一步观察，名词性从句','the rest of the journey':'想了解的相关方面','How did you find the cooking workshop, and which place surprised you most?':'具体问题一，完整问句','whether travelling with your parents changed the way you planned each day':'具体问题二，whether 从句'},'具体感受及细节 → 两个相关追问 → 友好收尾','不是写一封正式咨询公函；询问必须落到旅行或视频细节，不能只说 tell me more。',[('made me curious about','使我想进一步了解……'),('which place surprised you most','哪个地方最让你意外'),('warm and personal','温暖且有亲近感')],header='Dear Jack,',footer='Best wishes,\nLi Ming',source='S19、S36、S40；交流任务据所给题干改编，措辞与情节新编')
add('A09','感谢信','书信','新编题：感谢 Smith 教授在你准备学术报告时给予的具体帮助，说明帮助带来的变化。','''Now that my presentation is over, I want to thank you for helping me prepare it. Your advice made a real difference to how I explained my ideas.

When my first draft was too broad, you helped me choose a clear question and remove unrelated material. You also showed me how to use examples instead of reading directly from my notes. As a result, I felt more confident and could respond calmly to the audience's questions. More than the presentation itself, I value the careful way of thinking that you encouraged.

I will use what I learned in future work. Thank you again for your time and patience.''',{'my presentation':'得到帮助的事情','helping me prepare it':'对方给予的帮助，动名词','how I explained my ideas':'改变的方面，名词性从句','When my first draft was too broad, you helped me choose a clear question and remove unrelated material.':'帮助一，完整句','You also showed me how to use examples instead of reading directly from my notes.':'帮助二，完整句','I felt more confident and could respond calmly to the audience\'s questions':'具体结果，完整分句','the presentation itself':'本次成果','the careful way of thinking':'长远收获'},'感谢具体事项 → 帮助及其效果 → 延伸收获、再次致谢','感谢信需要“你做了什么＋这对我有什么用”；不用频繁重复 heartfelt/sincere 来凑词。',[('make a real difference to','对……有切实影响'),('respond calmly to','冷静回应……'),('your time and patience','您付出的时间和耐心')],header='Dear Professor Smith,',footer='Yours sincerely,\nLi Ming')
add('A10','道歉信','书信','新编题：借用朋友 Alex 的书后不慎损坏，致歉、说明经过并提出具体补救方案。','''I owe you an apology for damaging the book you lent me. I accidentally spilled water on it yesterday, and several pages are now stained.

I should have kept it away from my desk while I was drinking. I understand that you need the book for your course, so I have ordered a replacement of the same edition. It should arrive on Thursday. Until then, you are welcome to use my copy, which covers the same material. If this arrangement causes any difficulty, please tell me and I will find another solution.

I am sorry for being careless and for disrupting your study plans.''',{'damaging the book you lent me':'过失，动名词','I accidentally spilled water on it yesterday, and several pages are now stained.':'事件经过及影响，完整句','I should have kept it away from my desk while I was drinking.':'承认本可避免的过失，完整句','you need the book for your course':'对方的实际需要，完整分句','I have ordered a replacement of the same edition':'补救行动，完整分句','It should arrive on Thursday.':'补救完成时间，完整句','you are welcome to use my copy, which covers the same material':'临时替代办法，完整分句','being careless and for disrupting your study plans':'需要道歉的行为与影响，动名词结构'},'具体道歉 → 经过、承担责任、可行补救 → 再次致歉','解释原因不能替代承担责任；不要只说以后注意而不给对方可执行的解决办法。',[('owe you an apology for','应为……向你道歉'),('a replacement of the same edition','同一版本的替换本'),('disrupt your study plans','打乱你的学习计划')],header='Dear Alex,',footer='Best wishes,\nLi Ming')
add('A11','投诉信','书信','新编题：从商店购买的台灯无法正常使用；说明问题、影响和要求，语气坚定而礼貌。','''The desk lamp I bought from your store on Monday stopped working after two evenings. I am contacting you to request a replacement.

Although I followed the instructions, the light now switches off whenever I adjust its angle. This makes it unsuitable for reading and has interrupted my evening study. I have checked the power supply, so the problem appears to be with the lamp itself. The receipt and photographs of the item are available if you need them.

Please let me know how to return it and when a replacement can be provided. I would appreciate a reply within the next few days.''',{'The desk lamp':'购买的物品','Monday':'购买时间','stopped working after two evenings':'问题出现情况，过去式动词短语','a replacement':'合理诉求','the light now switches off whenever I adjust its angle':'具体故障，完整分句','This makes it unsuitable for reading and has interrupted my evening study.':'实际影响，完整句','I have checked the power supply, so the problem appears to be with the lamp itself.':'排查或交涉情况，完整句','The receipt and photographs of the item':'可提供的证据','within the next few days':'合理回复期限'},'交易及诉求 → 问题、影响与证据 → 处理方式和期限','事实与要求应清楚；没有题干依据，不写人身攻击、威胁或夸大的损失。',[('request a replacement','请求换货'),('appears to be with ...','看来出在……上'),('The receipt ... is available','可提供收据；注意主谓一致')],header='Dear Customer Service Team,',footer='Yours sincerely,\nLi Ming')
add('A12','咨询信','书信','新编题：准备参加暑期语言课程，向负责人询问课程安排、费用和报名条件。','''I am considering your summer language course and would like to clarify a few points before applying. My main aim is to become more confident in academic discussions.

Could you tell me how many hours of speaking practice are included each week? I would also like to know whether the fee covers learning materials or whether these must be purchased separately. As I will be travelling from another city, information about nearby accommodation would be useful. Finally, is an entrance test required, and when should applicants submit their results?

These details would help me plan my stay. Thank you for taking the time to answer my questions.''',{'your summer language course':'咨询的课程或项目','to become more confident in academic discussions':'个人目的，不定式','Could you tell me how many hours of speaking practice are included each week?':'具体问题一，完整问句','whether the fee covers learning materials or whether these must be purchased separately':'具体问题二，whether 从句','As I will be travelling from another city, information about nearby accommodation would be useful.':'额外信息需求与理由，完整句','is an entrance test required, and when should applicants submit their results':'具体问题三，疑问语序','plan my stay':'了解信息的用途，动词原形'},'背景与目的 → 三个相关问题 → 说明信息用途并致谢','Could you tell me 后用陈述语序：how many hours are included；不是 are how many hours。题目已有信息不重复问。',[('clarify a few points','澄清几个问题'),('be purchased separately','需要另行购买'),('submit their results','提交成绩／结果')],header='Dear Course Coordinator,',footer='Yours sincerely,\nLi Ming')
add('A13','请求信：请求帮助','书信','新编题：希望 Smith 教授审阅调查问卷，说明请求内容、困难和时间安排。','''Could you spare some time to review the questionnaire for our student reading survey? I would value your advice before we distribute it next week.

Our team has drafted eight questions, but we are unsure whether two of them might lead respondents towards a particular answer. Your experience in survey design would help us make the wording more balanced. I can send you the draft today, together with a short explanation of our research aim. Comments on those two questions would be enough, so a detailed review of the whole project is unnecessary.

Please let me know whether this would fit your schedule. Thank you for considering the request.''',{'review the questionnaire for our student reading survey':'请求对方做的事，动词原形','distribute it next week':'相关时限，动词短语','Our team has drafted eight questions, but we are unsure whether two of them might lead respondents towards a particular answer.':'已完成工作及困难，完整句','survey design':'对方的专长领域','make the wording more balanced':'希望获得的帮助，动词原形','the draft':'可提前提供的材料','our research aim':'材料的背景','Comments on those two questions would be enough, so a detailed review of the whole project is unnecessary.':'缩小请求范围以减轻负担，完整句'},'明确请求 → 为什么需要帮助、准备了什么 → 尊重对方时间','求助要说明具体任务和截止时间；不能把对方同意当作既成事实。',[('spare some time to do','抽时间做……'),('lead respondents towards a particular answer','诱导受访者选择特定答案'),('fit your schedule','符合您的时间安排')],header='Dear Professor Smith,',footer='Yours sincerely,\nLi Ming')
add('A14','申请信：项目／志愿者','书信','新编题：申请担任校园文化节志愿者；说明动机、相关经历和可服务时间。','''Please consider my application to volunteer at the campus cultural festival. I would enjoy helping visitors explore the exhibition and feel welcome on campus.

Last semester, I helped organise a student art show, where I answered questions and guided visitors between rooms. That experience taught me to give clear directions and remain patient when plans changed. I can communicate comfortably in English and am willing to learn the background of each display before the festival begins. I will be available throughout both days of the event.

I would welcome a brief interview to discuss how I could contribute. Thank you for reviewing my application.''',{'volunteer at the campus cultural festival':'申请参与的项目，动词原形','helping visitors explore the exhibition and feel welcome on campus':'申请动机，动名词','Last semester, I helped organise a student art show, where I answered questions and guided visitors between rooms.':'相关经历，完整句','give clear directions and remain patient when plans changed':'经验带来的能力，动词原形','I can communicate comfortably in English and am willing to learn the background of each display before the festival begins.':'其他匹配条件，完整句','throughout both days of the event':'可参与时间'},'申请及动机 → 经历证据、能力和时间 → 面谈意愿','按申请要求选经历，不编造题目相冲突的身份；如申请奖学金或交换项目，要改成对应资格。',[('Please consider my application to ...','请考虑我申请……'),('remain patient when plans changed','安排变化时仍保持耐心'),('be available throughout ...','在……全程有空')],header='Dear Festival Coordinator,',footer='Yours sincerely,\nLi Ming')
add('A15','求职信','书信','新编题：申请校报编辑助理；写明申请岗位、与工作匹配的技能和可到岗时间。','''Your advertisement for an editorial assistant caught my attention because the role combines writing with careful fact checking. I would like to apply for the position.

As an English major, I have edited articles for our student newsletter and worked with writers to improve clarity. I also maintain a simple checklist for names, dates and sources, which helps me catch mistakes before publication. These experiences would allow me to support your editors with both language and accuracy. I can start after the current term ends.

My resume provides further details of my experience. I would appreciate an opportunity to discuss the role in an interview.''',{'an editorial assistant':'岗位名称，含冠词','the role combines writing with careful fact checking':'岗位吸引你的原因，完整分句','an English major':'申请者身份，含冠词','I have edited articles for our student newsletter and worked with writers to improve clarity':'经历一，完整分句','I also maintain a simple checklist for names, dates and sources, which helps me catch mistakes before publication.':'经历二及效果，完整句','support your editors with both language and accuracy':'对岗位的贡献，动词原形','after the current term ends':'到岗时间'},'申请岗位 → 经历与职责匹配 → 到岗时间和面试','简历若未要求随附，可写 provides details；考试允许合理补细节，但不能用真实姓名或违反题干身份。',[('careful fact checking','仔细核查事实'),('improve clarity','提升表达清晰度'),('before publication','发表之前')],header='Dear Hiring Manager,',footer='Yours sincerely,\nLi Ming',source='S05、S18、S29；岗位申请功能综合重写')
add('A16','祝贺信','书信','新编题：朋友 Anna 获得演讲比赛奖项，向她祝贺并谈及你观察到的努力。','''What wonderful news that you won the university speaking competition! You have every reason to feel proud, and I am very happy for you.

I still remember how carefully you revised your speech and practised the opening until it sounded natural. You also listened seriously to other people's suggestions, even when making changes took extra time. The award recognises that effort as well as your ability to connect with an audience. I hope the experience encourages you to take on further speaking opportunities.

When you are free, let us celebrate over lunch. I would love to hear which part of the final round you enjoyed most.''',{'you won the university speaking competition':'获奖或喜讯，完整分句','how carefully you revised your speech and practised the opening until it sounded natural':'见证过的努力，名词性从句','You also listened seriously to other people\'s suggestions, even when making changes took extra time.':'另一项具体努力，完整句','connect with an audience':'相关能力，动词原形','take on further speaking opportunities':'未来祝愿，动词原形','the final round':'对应活动阶段'},'直接祝贺 → 努力细节与成绩相连 → 祝愿或庆祝','祝贺 on an achievement；不要写 congratulate you for。对方的努力应与所获成绩相关。',[('have every reason to feel proud','完全有理由为自己自豪'),('connect with an audience','与听众建立交流'),('recognise that effort','肯定这份努力')],header='Dear Anna,',footer='Best wishes,\nLi Ming')
add('A17','欢迎信','书信','新编题：以校园伙伴身份欢迎新来的国际学生，介绍报到安排并提供帮助。','''Welcome to our university! As your student buddy, I look forward to helping you settle into campus life during your first week.

We will meet at the international office at nine on Monday morning. After registration, I can show you the library, dining hall and student service centre. Please bring your passport and admission letter, as the staff will need them to complete the paperwork. There will also be an informal gathering where you can meet other new students and ask questions about daily life.

If your arrival time changes, send me a message. I hope your first days here will be comfortable and enjoyable.''',{'our university':'欢迎加入的单位','your student buddy':'你的身份','during your first week':'协助时段','at the international office at nine on Monday morning':'见面地点和时间','After registration, I can show you the library, dining hall and student service centre.':'具体安排，完整句','your passport and admission letter':'要准备的材料','complete the paperwork':'材料用途，动词原形','an informal gathering':'后续活动，含冠词','your arrival time':'可能需要协调的事项'},'欢迎及身份 → 报到、材料和适应安排 → 联系帮助','welcome to 后接地点或机构；welcome you to 后才可接动词。欢迎信要有帮助新人落地的信息。',[('settle into campus life','适应校园生活'),('complete the paperwork','完成手续'),('an informal gathering','轻松的聚会')],header='Dear New Students,',footer='Best wishes,\nLi Ming')
add('A18','辞职信','书信','新编题：兼职编辑工作与毕业研究冲突，向 Wang 先生说明辞职决定、原因和交接办法。','''After careful consideration, I have decided to leave my position as a part-time editor at the end of this month. I am grateful for the guidance you have given me.

My final research project now requires more time than I expected, and I cannot give both responsibilities the attention they deserve. Rather than let unfinished work affect the team, I would like to arrange a smooth handover. I will complete my current articles and prepare notes on all outstanding tasks. I can also explain our editing process to whoever takes over.

Thank you for your understanding. Working with the team has been a valuable learning experience.''',{'a part-time editor':'当前岗位，含冠词','at the end of this month':'离职时间','My final research project now requires more time than I expected, and I cannot give both responsibilities the attention they deserve.':'辞职原因，完整句','complete my current articles and prepare notes on all outstanding tasks':'交接措施，动词原形','explain our editing process':'补充协助，动词原形'},'明确决定与离职日期 → 合理原因、交接安排 → 感谢','不要只说抱歉而不说辞职；outstanding tasks 在此指未完成事项，不是优秀任务。',[('arrange a smooth handover','安排顺利交接'),('outstanding tasks','尚未完成的工作'),('whoever takes over','接手的人')],header='Dear Mr. Wang,',footer='Yours sincerely,\nLi Ming',source='S05、S18、S31；辞职功能与交接思路综合重写')
add('A19','婉拒信','书信','新编题：感谢朋友邀请参加周六活动，解释不能出席的原因并提出其他参与方式。','''Thank you for inviting me to help at the community book fair. I would have enjoyed taking part, but I cannot attend this Saturday.

I have already agreed to accompany my grandfather to a medical appointment that morning, and it cannot easily be rearranged. I am sorry to miss an event that brings books to more families. If it would help, I could sort the donated books on Friday evening or prepare labels before the fair. That way, I could still support the team without disrupting the arrangements.

I hope the day goes well. Please tell me whether either of these alternatives would be useful.''',{'help at the community book fair':'对方邀请的活动，动词原形','this Saturday':'无法出席的时间','I have already agreed to accompany my grandfather to a medical appointment that morning, and it cannot easily be rearranged.':'无法出席的原因，完整句','an event that brings books to more families':'对活动价值的认可','sort the donated books on Friday evening or prepare labels before the fair':'两个替代协助方案，动词原形'},'感谢并婉拒 → 合理原因与替代办法 → 祝愿及确认','未承诺参加时主要是婉拒；已答应却失约时改用 A10 道歉逻辑，不虚构很严重的事故作借口。',[('cannot easily be rearranged','不容易改期'),('without disrupting the arrangements','不打乱已有安排'),('either of these alternatives','这两个替代方案中的任何一个')],header='Dear Alex,',footer='Best wishes,\nLi Ming')
add('A20','活动通知','通知','新编题：学生会发布旧物修理工作坊通知，介绍活动、参加要求及报名办法。','''A repair workshop will take place in the student centre from two to four on Friday afternoon. All students interested in giving old items a second life are welcome.

Experienced volunteers will demonstrate basic repairs and guide participants through simple tasks. Please bring one small item, such as a bag or a piece of clothing, that needs attention. Electrical appliances cannot be accepted because specialist equipment is unavailable. Tools and basic materials will be provided at the venue.

To reserve a place, register at the student service desk by Wednesday. Places are limited, so early registration is recommended. Come and discover what you can repair yourself.''',{'A repair workshop':'活动名称，含冠词','in the student centre from two to four on Friday afternoon':'地点与时间','giving old items a second life':'参与者兴趣，动名词','Experienced volunteers will demonstrate basic repairs and guide participants through simple tasks.':'活动内容，完整句','one small item, such as a bag or a piece of clothing, that needs attention':'需携带物品','Electrical appliances cannot be accepted because specialist equipment is unavailable.':'限制及原因，完整句','Tools and basic materials':'主办方提供的用品','at the student service desk by Wednesday':'报名地点及截止时间','what you can repair yourself':'活动收获，名词性从句'},'活动及对象 → 内容、要求和保障 → 报名行动','通知有标题和发布者，不写 Dear 或 Yours。落款与日期服从题目，不必擅加个人身份。',[('give old items a second life','让旧物重新发挥用途'),('at the venue','在活动场地'),('reserve a place','预约名额')],header='NOTICE\nRepair Workshop',footer="Students' Union",source='S16、S18、S19、S31；通知结构与活动信息综合重写')
add('A21','招募通知','通知','新编题：为口述历史项目招募四名学生志愿者，写清职责、要求、培训与申请方式。','''Four student volunteers are needed for a community oral history project next month. The team will record residents' memories and prepare short written summaries.

Volunteers will help arrange interviews, check recordings and organise photographs. Applicants should be patient listeners, write clearly in English and be available on two Saturday mornings. Previous interviewing experience would be helpful, but training will be provided. All participants must respect residents' privacy and ask permission before recording or sharing their stories.

Please submit a short statement of interest to the student service desk by Friday. Include your available times and any relevant experience. Selected applicants will be contacted for a brief meeting.''',{'Four':'人数','a community oral history project':'项目名称，含冠词','next month':'服务时间','The team will record residents\' memories and prepare short written summaries.':'项目目标，完整句','arrange interviews, check recordings and organise photographs':'岗位职责，动词原形','be patient listeners, write clearly in English and be available on two Saturday mornings':'任职要求，动词原形','Previous interviewing experience':'有帮助但非必需的经历','respect residents\' privacy and ask permission before recording or sharing their stories':'特别要求，动词原形','a short statement of interest':'申请材料','to the student service desk by Friday':'提交地点及期限'},'招募岗位 → 职责、条件和培训 → 如何申请','duties 和 requirements 必须分别写到；不能只介绍活动意义或罗列性格词。',[('a statement of interest','简短的申请意向说明'),('relevant experience','相关经验'),('Selected applicants will be contacted','将联系入选的申请者')],header='NOTICE\nVolunteers Wanted',footer='Project Team',source='S16、S18、S19、S29；招募任务综合重写')
add('A22','寻物启事','告示','新编题：你在图书馆丢失蓝色笔记本，发布启事，给出特征、可能遗失地点和联系方式。','''I am looking for a blue notebook that I lost in the university library on Tuesday afternoon. I last used it at a desk near the second-floor windows.

The notebook has a plain cover and a small white label on the back. It contains handwritten notes for my final research project, so it is particularly important to me. My name is written inside the front cover. If you have found it or handed it to a member of staff, please let me know where it can be collected.

You can leave a message for Li Ming at the library service desk. Any help would be greatly appreciated.''',{'a blue notebook':'丢失物品，含冠词','in the university library on Tuesday afternoon':'丢失地点及时间','at a desk near the second-floor windows':'最后使用地点','The notebook has a plain cover and a small white label on the back.':'外观特征，完整句','handwritten notes for my final research project':'物品内容或用途','My name is written inside the front cover.':'辨认线索，完整句','at the library service desk':'联系方式或联系地点'},'丢失物品、时间地点 → 特征及用途 → 联系与致谢','不必虚构高额酬金；考试中的姓名与联系方式须服从题目。此处联系地点为新编情境。',[('a plain cover','素色封面'),('hand it to a member of staff','把它交给工作人员'),('where it can be collected','到哪里领取')],header='LOST\nA Blue Notebook',footer='Li Ming',source='S05、S18、S19；告示信息功能综合重写')
add('A23','招领启事','告示','新编题：活动结束后捡到背包，写招领启事，说明发现地点、领取方式和认领核实要求。','''A backpack was found beside the entrance to the student centre after yesterday's music workshop. It has been handed to the service desk for safekeeping.

The bag contains study materials and a few personal items. To make sure it is returned to the right person, the owner should describe its colour and identify at least two things inside. Please bring a student card or another form of identification when collecting it. The desk is open from nine in the morning to five in the afternoon on weekdays.

If you know someone who is missing a backpack, please pass on this message. Thank you for your help.''',{'A backpack':'拾得物品，含冠词','beside the entrance to the student centre':'拾得地点','yesterday\'s music workshop':'拾得时间或活动','the service desk':'保管与领取地点','The bag contains study materials and a few personal items.':'概括物品内容，完整句','describe its colour and identify at least two things inside':'核实方式，动词原形','a student card or another form of identification':'领取凭证','from nine in the morning to five in the afternoon on weekdays':'领取时间','a backpack':'相应物品，含冠词'},'物品与地点 → 保管、核实及领取要求 → 帮助转告','标题用 FOUND；不把所有可核实细节都公开，也不要把招领写成自己在找失物。',[('for safekeeping','为妥善保管'),('a form of identification','一种身份证明'),('pass on this message','转告此消息')],header='FOUND\nBackpack at the Student Centre',footer='Student Service Centre',source='S05、S18、S19；告示功能迁移重写')
add('A24','倡议书','倡议','新编题：学生会倡议同学减少食堂食物浪费，说明问题并提出可执行的行动。','''Too much food is left on trays after meals in our dining hall. We invite everyone to help reduce this waste through a few manageable changes.

Choose a smaller portion when you are unsure how much you can finish, and return for more if necessary. When eating with friends, discuss quantities before ordering shared dishes. Students can also tell the dining hall which portion sizes would better suit their needs. These actions save food without requiring anyone to skip a meal or eat less than they need.

Let us begin with our next meal and encourage one another to make careful choices. Every finished portion is a useful step.''',{'Too much food is left on trays after meals in our dining hall.':'观察到的问题，完整句','reduce this waste':'倡议目标，动词原形','Choose a smaller portion when you are unsure how much you can finish, and return for more if necessary.':'行动一，完整句','When eating with friends, discuss quantities before ordering shared dishes.':'行动二，完整句','Students can also tell the dining hall which portion sizes would better suit their needs.':'反馈或集体措施，完整句','save food without requiring anyone to skip a meal or eat less than they need':'行动效果及合理边界，动词原形','our next meal':'起步场景','Every finished portion is a useful step.':'呼吁收束，完整句'},'问题 → 个人与集体可行行动 → 呼吁参与','倡议要让读者知道现在能做什么；区别于报名通知，不能只写时间地点。若题目指定信件格式，另加称呼。',[('manageable changes','容易实行的改变'),('portion sizes','每份食物的分量'),('make careful choices','认真作出选择')],header='A Call to Reduce Food Waste',footer="Students' Union",source='S18、S19；行动与意义功能综合重写')
add('A25','会议纪要','纪要','新编题：记录读书会会议：讨论场地，决定使用图书馆；Chen 负责海报、Wang 负责报名，下周一前完成，周三复核。','''The committee met to finalise arrangements for the campus reading event. Members discussed the venue, registration process and publicity materials.

After comparing two available rooms, the group agreed to use the library seminar room because it offered enough seating and a quiet setting. Chen will prepare the poster, while Wang will collect registrations and check participant numbers. Both tasks must be completed by next Monday. Members also agreed that each discussion group should have a student facilitator to keep the conversation focused.

The chair will review progress at a short meeting on Wednesday. Any difficulties should be reported in advance so that the arrangements can be adjusted.''',{'the campus reading event':'会议涉及事项','the venue, registration process and publicity materials':'讨论议题','After comparing two available rooms, the group agreed to use the library seminar room because it offered enough seating and a quiet setting.':'决定及理由，完整句','Chen will prepare the poster, while Wang will collect registrations and check participant numbers.':'负责人和任务，完整句','next Monday':'完成期限','Members also agreed that each discussion group should have a student facilitator to keep the conversation focused.':'另一项决定，完整句','Wednesday':'检查进度的时间'},'会议事实 → 决议、负责人和期限 → 后续跟进','讨论用过去时；待办可用 will。纪要记录已形成的决议，不写邀请、个人感想或未在会议中决定的内容。',[('finalise arrangements','确定最终安排'),('a student facilitator','学生讨论引导员'),('review progress','检查进展')],header='Minutes of the Reading Club Meeting\nDate: 12 May 2026\nPlace: Room 201\nPresent: Li Ming, Chen and Wang',footer='Recorded by: Li Ming',source='S08、S16、S18、S19、S29；纪要结构重写')
add('A26','备忘录','备忘录','新编题：向活动团队说明房间更换，列出需要完成的工作、负责人和确认期限。','''The reading workshop has been moved to Room 305 because the original room is undergoing repairs. The date and starting time remain unchanged.

Please update the registration page and replace the signs at the building entrance. Chen should check that the new room has enough chairs, while Wang should test the projector before Thursday afternoon. We also need to email registered participants with the new location and a simple map. Anyone who cannot receive email should be contacted by phone.

Please confirm completion of your tasks by four on Thursday. Let me know immediately if anything may delay the preparations, so we can arrange additional help.''',{'The reading workshop':'活动名称','Room 305':'新地点','the original room is undergoing repairs':'变动原因，完整分句','update the registration page and replace the signs at the building entrance':'需要完成的工作，动词原形','Chen should check that the new room has enough chairs, while Wang should test the projector before Thursday afternoon.':'明确分工，完整句','email registered participants with the new location and a simple map':'通知办法，动词原形','four on Thursday':'确认期限'},'变更事实 → 操作要求和分工 → 确认时限','To／From／Date／Subject 四项醒目；备忘录通常不加 Dear 和 Yours，与记录过去会议的 minutes 区分。',[('remain unchanged','保持不变'),('registered participants','已报名参加者'),('confirm completion','确认已完成')],header='MEMO\nTo: Workshop Team\nFrom: Li Ming\nDate: 12 May 2026\nSubject: Room Change',source='S19 第9页、S29；备忘录体裁与安排功能综合新编')
add('B01','静态构成：饼图／单选比例','大作文','新编数据：某校学生最偏好的阅读方式（单选）：纸质书 45%，电子书 35%，有声书 20%。要求概述数据并评论。','''Reading preferences are divided among three formats in the pie chart. Printed books lead with 45% of the students surveyed, compared with 35% for electronic books and 20% for audiobooks. Print is the largest category, although digital formats together attract more than half of the respondents.

The pattern may reflect the different situations in which people read. A printed book can offer a focused experience away from screen notifications. Electronic books, meanwhile, are easy to carry and search, while audio allows reading to fit around other activities. These advantages help explain why no single format attracts everyone. Preference may depend on the task as much as on the reader.

Libraries could respond by offering a balanced collection and helping students choose suitable formats. The aim should be to make useful reading easier, with different resources supporting different needs. A popular format is valuable when it serves a clear reading purpose.''',{'Reading preferences':'调查主题','three formats':'类别总数与类别名称','the pie chart':'图表类型','Printed books':'最大类别','45%':'最大类别占比','the students surveyed':'调查对象','35% for electronic books and 20% for audiobooks':'另外两类及比例','Print is the largest category, although digital formats together attract more than half of the respondents.':'准确概括主要对比，完整句','the different situations in which people read':'合理解释方向','A printed book can offer a focused experience away from screen notifications.':'最大类别的优势，完整句','Electronic books, meanwhile, are easy to carry and search, while audio allows reading to fit around other activities.':'其他类别的优势，完整句','Preference may depend on the task as much as on the reader.':'解释的补充，完整句','Libraries':'适合采取行动的主体','offering a balanced collection and helping students choose suitable formats':'具体措施，动名词','The aim should be to make useful reading easier, with different resources supporting different needs.':'措施的目标，完整句','A popular format is valuable when it serves a clear reading purpose.':'贴题结论，完整句'},'对象与构成 → 最大项及关键对比 → 用途差异解释 → 多样化供给','45% 是最大项，不是 majority；只有互斥且同一总体的类别才能相加。这里电子书与有声书合计55%。',[('the students surveyed','受调查的学生；不要写全部大学生'),('a focused experience','专注的体验'),('a balanced collection','均衡配置的馆藏')],source='S01、S04、S11、S17、S35；静态对比与需求分析综合重写')
add('B02','静态多选：柱状图／调查动机','大作文','新编数据：居民选择社区课程时的考虑因素，可多选：时间方便 68%，实用内容 56%，低费用 42%，结交朋友 27%。要求描述并评论。','''Convenient timing is the most frequently selected reason for choosing community courses, mentioned by 68% of respondents. Practical content follows at 56%, while low fees and opportunities to meet people receive 42% and 27%. Since respondents could select several reasons, the percentages describe overlapping preferences rather than parts of a single total.

These results suggest that a course must first fit into people's daily lives. An interesting class may still be difficult to attend if it conflicts with work or family duties. Practical content can provide an additional reason to participate because learners can use what they learn outside the classroom. Price also matters, though it is selected less often than timing or content.

Organisers could therefore offer several time slots and explain the practical value of each course. Keeping fees reasonable would further improve access. Such arrangements would address the concerns actually reported in the survey.''',{'Convenient timing':'最高项因素','community courses':'调查事项','68%':'最高比例','Practical content follows at 56%, while low fees and opportunities to meet people receive 42% and 27%.':'其他关键类别及数值，完整句','These results suggest that a course must first fit into people\'s daily lives.':'主要结果的合理解读，完整句','An interesting class may still be difficult to attend if it conflicts with work or family duties.':'解释最重要因素，完整句','Practical content can provide an additional reason to participate because learners can use what they learn outside the classroom.':'解释第二项因素，完整句','Price also matters, though it is selected less often than timing or content.':'补充一个相关对比，完整句','Organisers':'行动主体','offer several time slots and explain the practical value of each course':'与主要结果对应的措施，动词原形','Keeping fees reasonable':'补充措施，动名词'},'按选择率排序 → 说明多选口径 → 解释主要因素 → 对应措施','多选合计193%并非数据错；不能写剩余比例，也不能把68%与56%相加后称为124%的人。',[('overlapping preferences','可重叠的偏好'),('conflict with work or family duties','与工作或家庭责任冲突'),('offer several time slots','提供多个时段')],source='S09 第5页、S17、S35；静态多选口径综合新编')
add('B03','静态表格：不同群体的对比','大作文','新编数据：三个年龄组对某社区服务满意／一般／不满意的比例：18—29岁为65／25／10%，30—49岁为50／30／20%，50岁及以上为70／20／10%。要求描述并评论。','''Satisfaction with the community service varies across the three age groups in the table. The figure is highest among residents aged fifty and above, at 70%, and lowest among those aged thirty to forty-nine, at 50%. The youngest group records 65%. Dissatisfaction reaches 20% in the middle group, twice the level in either of the other groups.

Different needs may help explain this contrast. Residents balancing employment and family care may find standard service hours less convenient. Older users may value regular personal assistance, while younger adults may prefer quick online access. These are possible explanations, and further feedback would be needed to identify the actual problems. The figures alone do not reveal individual experiences.

A useful response would be to ask each group what needs improvement and test flexible service hours. Improvements should address specific difficulties while preserving features that users already value, rather than treating all residents alike.''',{'Satisfaction with the community service':'调查指标','the three age groups':'对比群体','residents aged fifty and above, at 70%':'最高组及比例','those aged thirty to forty-nine, at 50%':'最低组及比例','The youngest group records 65%.':'另一关键数据，完整句','Dissatisfaction reaches 20% in the middle group, twice the level in either of the other groups.':'第二个维度的对比，完整句','Residents balancing employment and family care may find standard service hours less convenient.':'对组间差异的合理解释一，完整句','Older users may value regular personal assistance, while younger adults may prefer quick online access.':'合理解释二，完整句','ask each group what needs improvement and test flexible service hours':'收集反馈与改进措施，动词原形'},'横向比较主要指标 → 纵向补充另一指标 → 群体需求差异 → 精准改善','年龄组之间的比较不代表同一批人随年龄增长的变化；不同分母的百分比不可直接相加为整体满意率。',[('twice the level in ...','是……水平的两倍'),('preserving features that users already value','保留使用者已经认可的特点'),('treating all residents alike','以同一方式对待所有居民')],source='S01、S09、S17、S35；表格与群体对比综合重写')
add('B04','动态单指标：上升／下降','大作文','新编数据：某市公共交通出行占比，2020年30%，2022年36%，2024年45%。要求概述趋势并评论。','''Public transport accounted for a growing share of journeys in the city between 2020 and 2024. The proportion increased from 30% to 36% in 2022 and reached 45% by 2024, a total gain of fifteen percentage points. The increase was larger in the second half of the period.

Several practical factors may have encouraged this shift. More convenient routes could make public transport a realistic choice for journeys that once required a car. Reliable arrival information may also reduce uncertainty and make transfers easier to plan. Lower travel costs would provide another incentive, especially for people who commute regularly. These possibilities link the trend to everyday decisions, although the chart itself does not establish the causes.

To sustain the improvement, the city should focus on reliability, connections and access for people with limited mobility. A service that works well in ordinary situations is more likely to remain useful over time.''',{'Public transport':'出行或行为类别','journeys in the city':'统计总体','2020 and 2024':'起止年份，保留 and','The proportion increased from 30% to 36% in 2022 and reached 45% by 2024, a total gain of fifteen percentage points.':'含起终点、关键中点及变化量的准确描述，完整句','The increase was larger in the second half of the period.':'主要阶段特征，完整句','More convenient routes could make public transport a realistic choice for journeys that once required a car.':'可能原因一及机制，完整句','Reliable arrival information may also reduce uncertainty and make transfers easier to plan.':'可能原因二及机制，完整句','Lower travel costs would provide another incentive, especially for people who commute regularly.':'贴题补充解释，完整句','To sustain the improvement, the city should focus on reliability, connections and access for people with limited mobility.':'具体主体和行动，完整句','A service that works well in ordinary situations is more likely to remain useful over time.':'贴题收尾，完整句'},'时间、指标和增量 → 两个解释机制 → 持续改善条件','30%到45%是上升15个百分点，也相当于相对增长50%；下降题须同步改首句 growing、第二段 shift 与结尾 improvement 的评价。',[('a total gain of ... percentage points','共增加……个百分点'),('provide another incentive','提供另一种动力'),('people with limited mobility','行动不便者')],source='S01、S04、S17、S26、S30；动态描述与机制分析综合重写')
add('B05','动态多指标：升降对照／结构变化','大作文','新编数据：某校毕业去向，2020年直接就业60%、继续升学25%、其他15%；2025年分别为45%、40%、15%。要求描述并评论。','''The chart shows a change in graduates' plans between 2020 and 2025. Direct employment fell from 60% to 45%, while further study rose from 25% to 40%. Other choices remained at 15%. Employment was still the largest category in 2025, but its lead over further study narrowed from thirty-five to five percentage points.

One possible explanation is that more graduates see additional education as useful preparation for specialised work. They may also want time to explore their interests before committing to a career. Meanwhile, direct employment continues to offer immediate income and practical experience. The changing shares therefore need not mean that one route is suitable for everyone. Costs, interests and career requirements can lead to different reasonable choices.

Universities should provide information on both employment and further study, including their demands and likely benefits. Advice based on individual circumstances would help students choose a route they can realistically pursue.''',{'graduates\' plans':'调查主题','2020 and 2025':'起止年份，保留 and','Direct employment fell from 60% to 45%, while further study rose from 25% to 40%.':'一降一升的准确描述，完整句','Other choices remained at 15%.':'保持不变项，完整句','Employment was still the largest category in 2025, but its lead over further study narrowed from thirty-five to five percentage points.':'排序与差距变化，完整句','more graduates see additional education as useful preparation for specialised work':'可能原因，完整分句','They may also want time to explore their interests before committing to a career.':'进一步解释，完整句','Meanwhile, direct employment continues to offer immediate income and practical experience.':'另一选项的合理价值，完整句','Costs, interests and career requirements':'影响选择的具体因素','Universities':'提出措施的主体','provide information on both employment and further study, including their demands and likely benefits':'措施，动词原形'},'分别写升降和不变 → 概括差距缩小 → 解释选择差异 → 给出分情境建议','占比下降不能推出就业人数下降；没有毕业生总人数，就只讨论份额。最大类别与增长最快类别也不是一回事。',[('its lead ... narrowed','其领先幅度缩小'),('commit to a career','确定职业方向'),('individual circumstances','个人具体情况')],source='S01、S04、S17、S26、S30、S35；多指标对比综合重写')
add('B06','波动趋势：先升后降／转折','大作文','新编数据：某公共图书馆年度到访人次，2021年12万、2022年18万、2023年16万、2024年20万。要求概述并评论。','''Annual visits to the public library followed an uneven upward path from 2021 to 2024. They rose from 120,000 to 180,000, slipped to 160,000 in 2023, and then reached 200,000 in the final year. Despite the temporary decline, the final figure was well above the starting level and was the highest recorded.

This pattern may reflect both growing demand and changes in how easily people could use the library. Attractive events can bring in more visitors, while opening hours and access conditions may affect attendance from year to year. A temporary fall should therefore be interpreted alongside the longer pattern. It does not by itself show that residents have lost interest in reading.

The library could compare attendance with its programme schedule and collect visitors' feedback before making changes. Maintaining dependable services and offering useful activities would be a sensible response. The priority is to understand the variation and improve the experience behind the numbers.''',{'Annual visits to the public library':'指标与主体','2021 to 2024':'起止年份，保留 to','They rose from 120,000 to 180,000, slipped to 160,000 in 2023, and then reached 200,000 in the final year.':'包括转折点的完整描述句','Despite the temporary decline, the final figure was well above the starting level and was the highest recorded.':'整体特征概括，完整句','growing demand and changes in how easily people could use the library':'可能相关的两个因素','Attractive events can bring in more visitors, while opening hours and access conditions may affect attendance from year to year.':'解释作用机制，完整句','residents have lost interest in reading':'不能仅由短期变化推出的判断，完整分句','The library':'行动主体','compare attendance with its programme schedule and collect visitors\' feedback before making changes':'核实原因与改进的动作，动词原形','Maintaining dependable services and offering useful activities':'具体改进方向，动名词'},'按时间写关键转折 → 概括总趋势 → 谨慎解释 → 用反馈改善','有中途下降就不能写 rose steadily。此处统计到访人次，不是独立访客人数，不能把 visits 换成 visitors。',[('an uneven upward path','有波动的上升过程'),('slipped to','小幅回落至'),('the highest recorded','图中记录的最高值')],source='S01、S17、S26；转折与统计对象辨别综合新编')
add('B07','双图表：规模与使用情况','大作文','新编数据：图一，某市公园数量2019年40个、2024年60个；图二，2024年居民每周去公园次数，至少3次50%、1—2次35%、不足1次15%。要求概述两图并评论。','''The two charts describe the provision and use of public parks in a city. Park numbers increased from forty in 2019 to sixty in 2024. In the survey for 2024, half of residents reported visiting a park at least three times a week, while only 15% went less than once a week.

Together, the charts show expanded provision alongside frequent use. More nearby parks may make outdoor activity easier to fit into everyday routines. Safe paths, comfortable seating and space for exercise can also make visits appealing to different age groups. However, the data do not establish that the increase in park numbers caused the reported visiting pattern. Location and service quality may matter as much as the total number.

Future planning should therefore consider where parks are needed and how existing spaces are used. Listening to residents would help turn additional facilities into accessible places that support regular activity.''',{'the provision and use of public parks in a city':'两图的共同主题及各自维度','Park numbers increased from forty in 2019 to sixty in 2024.':'图一核心数据，完整句','In the survey for 2024, half of residents reported visiting a park at least three times a week, while only 15% went less than once a week.':'图二核心数据，完整句','expanded provision alongside frequent use':'两图支持的并列概括','More nearby parks may make outdoor activity easier to fit into everyday routines.':'可能联系机制，完整句','Safe paths, comfortable seating and space for exercise can also make visits appealing to different age groups.':'相关影响因素，完整句','the increase in park numbers caused the reported visiting pattern':'未经证明的因果，完整分句','Location and service quality may matter as much as the total number.':'补充考虑因素，完整句','where parks are needed and how existing spaces are used':'规划关注点，名词性从句','turn additional facilities into accessible places that support regular activity':'具体目标，动词原形'},'每幅图各取核心信息 → 并列联系 → 可能机制与条件 → 具体措施','第二幅图只有2024年，不能写居民访问频率“上升”。两图相关不能直接证明因果；先读清各图年份与单位。',[('provision and use','设施供给与使用情况'),('alongside frequent use','与频繁使用并存'),('as much as the total number','与总数量同样重要')],source='S01、S15、S17；双图综合与谨慎联系重写')
add('B08','图画材料：行为对比与寓意','大作文','新编图画题：两名学生准备同一份报告。一人只复制屏幕文字，另一人边阅读边记问题，并与同伴讨论。要求简述画面、解释寓意并评论。','''Two students are preparing the same report in different ways. One simply copies words from a screen, while the other writes down questions and discusses them with a classmate. Their contrasting actions draw attention to the difference between collecting information and understanding it.

Easy access to material can make learning faster, but speed alone does not ensure understanding. A student who asks why an explanation works is more likely to notice gaps and connect ideas. Discussion adds another useful step: explaining a point to someone else can reveal whether it is actually clear. Copying may produce a finished page, yet it offers little help when the learner must solve an unfamiliar problem.

A practical response is to turn reading into an active process. Students can summarise ideas in their own words, test them with examples and ask questions about unclear parts. These habits give the information a purpose beyond completing an assignment.''',{'Two students are preparing the same report in different ways.':'画面人物与情境，完整句','One simply copies words from a screen, while the other writes down questions and discusses them with a classmate.':'关键动作对比，完整句','collecting information and understanding it':'对应主题的两个概念','Easy access to material can make learning faster, but speed alone does not ensure understanding.':'明确立场及界限，完整句','A student who asks why an explanation works is more likely to notice gaps and connect ideas.':'理由一及机制，完整句','Discussion adds another useful step: explaining a point to someone else can reveal whether it is actually clear.':'理由二及机制，完整句','Copying may produce a finished page, yet it offers little help when the learner must solve an unfamiliar problem.':'反面行为的后果，完整句','turn reading into an active process':'行动方向，动词原形','Students can summarise ideas in their own words, test them with examples and ask questions about unclear parts.':'可操作措施，完整句','These habits give the information a purpose beyond completing an assignment.':'贴题收束，完整句'},'画面事实 → 行为差异与主题 → 机制论证 → 行动','只在题目实际给图画时使用；不用英语一20分、160—200词口径。画面未出现的心理和身份不要写成事实。',[('notice gaps and connect ideas','发现缺口并联系知识'),('in their own words','用自己的话'),('beyond completing an assignment','不止用于完成作业')],source='S01、S03、S11、S15、S21、S28；图画写法按英语二篇幅重写')
add('B09','文字材料：评述观点','大作文','新编材料观点：“Online learning should replace classroom teaching because it is more convenient.” 要求解释你是否同意，并用理由和例子支撑。','''The passage argues that online learning should replace classroom teaching because it offers greater convenience. I agree that flexibility is valuable, but I do not think convenience alone justifies replacing one form of education with another.

Online lessons allow students to revisit explanations and study when travel is difficult. These benefits can widen access to learning. However, a classroom also provides immediate discussion, shared practice and opportunities for teachers to notice confusion. For example, a student conducting a simple experiment may need direct guidance that a recorded video cannot provide. Different subjects and learners therefore call for different arrangements. The quality of teaching matters alongside the method of delivery.

A better approach is to combine the strengths of both forms where appropriate. Schools can use online resources for preparation and review while keeping classroom time for interaction and practical work. The choice should follow learning needs rather than a general preference for convenience.''',{'The passage argues that online learning should replace classroom teaching because it offers greater convenience.':'准确概括材料论点，完整句','I agree that flexibility is valuable, but I do not think convenience alone justifies replacing one form of education with another.':'自己的立场与限定，完整句','Online lessons allow students to revisit explanations and study when travel is difficult.':'承认合理之处，完整句','These benefits can widen access to learning.':'合理之处的价值，完整句','However, a classroom also provides immediate discussion, shared practice and opportunities for teachers to notice confusion.':'反向理由，完整句','a student conducting a simple experiment may need direct guidance that a recorded video cannot provide':'支撑立场的例子，完整分句','Different subjects and learners therefore call for different arrangements.':'根据例子作出推论，完整句','The quality of teaching matters alongside the method of delivery.':'补充判断，完整句','combine the strengths of both forms where appropriate':'解决方向，动词原形','Schools can use online resources for preparation and review while keeping classroom time for interaction and practical work.':'落实措施，完整句','The choice should follow learning needs rather than a general preference for convenience.':'与立场一致的结论，完整句'},'概括原观点与立场 → 承认合理点 → 理由与例子 → 回扣判断标准','必须回应材料真正的主张；如果题目问同意程度，要明说。不要把所有文字题都强套“问题—原因—措施”。',[('justify replacing ...','构成替换……的充分理由'),('where appropriate','在适宜的情况下'),('the method of delivery','教学内容的传递方式')],source='S01、S11、S15、S17、S21、S28；材料观点与有限同意论证重写')
add('B10','图画＋图表：复合材料','大作文','新编复合材料：图画中志愿者帮助老人使用医院自助机；图表显示某社区60岁以上居民预约方式，手机应用55%、电话30%、现场15%。要求描述材料并评论。','''In the drawing, a volunteer helps an older patient use a hospital self-service machine. The accompanying chart shows how residents aged over sixty book appointments: 55% use an app, 30% telephone the service and 15% visit in person. Together, the materials highlight both the reach of digital services and the continuing need for support.

An app can save travel and waiting time, especially for people who use smartphones confidently. Yet some residents may find unfamiliar instructions or small text difficult to follow. The volunteer's assistance illustrates one way to bridge that gap. The booking figures show that a substantial minority still choose other channels, although they do not tell us why each person makes that choice.

Hospitals should improve digital interfaces while keeping telephone and personal assistance available. Clear guidance and patient support would allow more people to benefit from convenient services without making a particular technology a condition for receiving care.''',{'In the drawing, a volunteer helps an older patient use a hospital self-service machine.':'图画事实，完整句','The accompanying chart shows how residents aged over sixty book appointments: 55% use an app, 30% telephone the service and 15% visit in person.':'图表对象与关键数据，完整句','both the reach of digital services and the continuing need for support':'两材料共同主题','An app can save travel and waiting time, especially for people who use smartphones confidently.':'积极价值，完整句','Yet some residents may find unfamiliar instructions or small text difficult to follow.':'现实困难，完整句','The volunteer\'s assistance illustrates one way to bridge that gap.':'图画与分析的联系，完整句','The booking figures show that a substantial minority still choose other channels, although they do not tell us why each person makes that choice.':'图表的合理解读与边界，完整句','Hospitals':'行动主体','improve digital interfaces while keeping telephone and personal assistance available':'对应措施，动词原形','Clear guidance and patient support would allow more people to benefit from convenient services without making a particular technology a condition for receiving care.':'有条件的结论，完整句'},'画面与数据分别概括 → 共同主题 → 价值和障碍 → 保留多渠道','app占55%可称 majority；选择电话或现场合计45%，不能由此断定45%的人不会用手机。画面与统计样本范围要分清。',[('the accompanying chart','随附图表'),('bridge that gap','弥合这一差距'),('a substantial minority','占比不小的少数群体')],source='S01、S15、S17；图画与图表联系综合新编')

